css:
* { margin: 0; padding: 0; box-sizing: border-box; }
    body { display: flex; justify-content: center; align-items: center; width: 100vw; height: 100vh; background: transparent; }

    .widget {
        position: relative;
        width: 100%;
        height: 100%;
        aspect-ratio: 1 / 1;
        max-width: 100vw;
        max-height: 100vh;
    }

    /* 文件夹外框（彻底断绝点击，防止抢占事件） */
    .folder-img {
        position: absolute;
        top: 0; left: 0;
        width: 100%; height: 100%;
        object-fit: contain; 
        z-index: 2;
        pointer-events: none; 
    }

    /* 中间照片区域（点击触发） */
    .photo-frame {
        position: absolute;
        top: 52%;           
        left: 50%;          
        transform: translate(-50%, -50%);
        width: 76%;         
        height: 58%;        

        overflow: hidden; 
        clip-path: inset(0 round 10px); 
        -webkit-clip-path: inset(0 round 10px);

        border-radius: 10px; 
        cursor: pointer;
        z-index: 10; /* 给极高的层级，保证一定能点到 */

        /* 添加一个极其微弱的背景色，防止图片加载间隙点击穿透 */
        background-color: rgba(0, 0, 0, 0.01);
    }

    /* 图片填满相框 */
    .inner-img {
        position: absolute;
        top: 0; left: 0;
        width: 100%; height: 100%;
        object-fit: cover;
        display: block;
        border-radius: 10px;
    }
